import {lessonPart as part, lessonExample as example, lessonChoice, lessonBuild as build} from './connections.js';

export const sequenceAndConditionSkills = {
  'te-kara-form': '動作順序・て形＋から',
  'te-kara-order': '動作順序・先完成哪一步',
  'to-condition': '條件と・操作與通常結果',
  'ba-condition': '條件ば・接法與成立條件',
  'nara-condition': '條件なら・根據前提給建議',
  'condition-context': '條件比較・前提與動作先後'
};

function check(id, use, context, answer, why, wrong) {
  return lessonChoice(id, use, context, [answer, ...Object.keys(wrong)], [answer], why, wrong);
}

const ticket = '{切符|きっぷ}を{受|う}け{取|と}っ';
const enter = '{会場|かいじょう}に{入|はい}ります';
const button = 'このボタンを{押|お}す';
const print = '{番号札|ばんごうふだ}が{出|で}ます';
const station = '{駅|えき}に{着|つ}い';
const contact = '{連絡|れんらく}してください';
const bus = 'バスで{行|い}く';
const timetable = '{先|さき}に{時刻表|じこくひょう}を{見|み}ましょう';

const afterReceiving = [
  part(ticket+'てから、','action','受け取る變成受け取って，再接から。這一步要先完成。'),
  part(enter,'action','拿到票之後才入場。')
];
const afterReceivingAlt = [
  part(ticket+'た{後|あと}で、','action','受け取る的た形是受け取った。後で把這件事當作時間基準。'),
  part(enter,'action','同樣先領票，再入場。')
];
const buttonResult = [
  part(button+'と、','action','押す是非過去普通形。と後面說一般操作結果。'),
  part(print,'action','機器會印出號碼牌。')
];
const showTicket = [
  part('{切符|きっぷ}を{見|み}せれば、','action','一段動詞見せる去る，接れば。'),
  part('{中|なか}に{入|はい}れます','action','出示票券後便具備可入場的條件。')
];
const ifBus = [
  part(bus+'なら、','action','以搭公車這個計畫為前提。'),
  part(timetable,'action','建議搭車前先查時刻表。')
];
const onceAtStation = [
  part(station+'たら、','action','着く → 着いた＋ら。以到站作為下一步的時機。'),
  part(contact,'action','到站後再聯絡。')
];

